def transform(grid):
    h, w = len(grid), len(grid[0])
    mr = next(r for r in range(h) if all(v == 3 for v in grid[r]))
    mc = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if r == mr or c == mc:
                out[r][c] = 3
                continue
            y = r if r < mr else h - 1 - r
            x = c if c < mc else w - 1 - c

            # Build nested, expanding rectangular outlines from the outside
            # of each quadrant. Odd-indexed columns form the vertical strokes;
            # each successive stroke starts farther down.
            on = False
            for k in range(1, max(h, w) + 1, 2):
                if x == k and y >= (k - 1) // 2:
                    on = True
                if y == k and x >= (k - 1) // 2:
                    on = True
            out[r][c] = 4 if on else 0
    return out
